package org.codex.nfsugpreview;
import java.nio.*;import java.nio.file.*;
public final class CorrectedWorldMeshTest {
 static void rejects(byte[] bytes){try{NativeScenePacket p=new NativeScenePacket(1,bytes);new NativeWorldMesh(p,new NativeWorldScene(p),0);throw new AssertionError("Unsupported source interpolation accepted");}catch(IllegalArgumentException expected){}}
 static void sourceGuards(byte[] original){ByteBuffer b=ByteBuffer.wrap(original.clone()).order(ByteOrder.LITTLE_ENDIAN);int model=b.getInt(36);b.putDouble(model+24,120.25);rejects(b.array());b=ByteBuffer.wrap(original.clone()).order(ByteOrder.LITTLE_ENDIAN);int identity=b.getInt(84),base=identity+8+b.getInt(identity+4)*20;if(base<b.capacity()){b.putDouble(base+8,.5);rejects(b.array());}}

 public static void main(String[] args)throws Exception{Path input=Paths.get(args[0]),output=Paths.get(args[1]);Files.createDirectories(output);int count=0,empty=0;try(DirectoryStream<Path> paths=Files.newDirectoryStream(input,"*.nsp")){for(Path f:paths){byte[] bytes=Files.readAllBytes(f);NativeScenePacket packet=new NativeScenePacket(1,bytes);NativeWorldScene world=new NativeWorldScene(packet);NativeWorldMesh mesh=new NativeWorldMesh(packet,world,0);if(world.surface(0).sourceCamera()!=null)sourceGuards(bytes);if(mesh.triangleVertices==0)empty++;FloatBuffer vertices=mesh.vertices();ByteBuffer data=ByteBuffer.allocate(vertices.remaining()*4).order(ByteOrder.LITTLE_ENDIAN);while(vertices.hasRemaining())data.putFloat(vertices.get());Files.write(output.resolve(f.getFileName()+".mesh"),data.array());DoubleBuffer camera=mesh.cameraVertices();ByteBuffer c=ByteBuffer.allocate(camera.remaining()*8).order(ByteOrder.LITTLE_ENDIAN);while(camera.hasRemaining())c.putDouble(camera.get());Files.write(output.resolve(f.getFileName()+".camera"),c.array());count++;}}if(count<12||empty<2)throw new AssertionError("Coverage");System.out.println("PASS_CORRECTED_WORLD_MESH cases="+count+" empty="+empty);}
}
